  "Free wait, price per minute and the no-show fee are the Pricing values of this zone, so there is one place to change them. The free wait is also the no-show wait: the driver can cancel for no-show when it ends.": "Gratis väntan, pris per minut och avgiften för utebliven resenär är zonens värden i Priser, så det finns ett ställe att ändra dem. Den gratis väntan är också väntan före utebliven: föraren kan avboka för utebliven resenär när den är slut.",
  "Free wait, then a price per minute. When the free wait ends the driver can also cancel for no-show and the rider pays the no-show fee. Extra rules change only the values you tick.": "Gratis väntan, sedan ett pris per minut. När den gratis väntan är slut kan föraren även avboka för utebliven resenär och resenären betalar avgiften. Extra regler ändrar bara de värden du kryssar i.",
