  "What a fleet owner gets from their drivers' rides, after commission.": "Vad en flottägare får från förarnas resor, efter provision.",
  "What a new driver must upload in this country. The driving licence is always needed.": "Vad en ny förare måste ladda upp i det här landet. Körkortet krävs alltid.",
  "What an admin picks when cancelling a trip from Trips. The codes are fixed by the shared contract.": "Det en admin väljer när en resa avbokas från Resor. Koderna bestäms av det gemensamma kontraktet.",
  "What changed": "Vad som ändrades",
  "What drivers and riders choose from when they cancel. Mark a reason “Doesn't count” and it never hurts the cancel rate or the late-cancel rule, for example a rider no-show, safety or a car problem. An empty language shows the English text.": "Det förare och resenärer väljer bland när de avbokar. Markera ett skäl ”Räknas inte” så påverkar det aldrig avbokningsgraden eller regeln för sen avbokning, till exempel en utebliven resenär, säkerhet eller ett bilproblem. Ett tomt språk visar den engelska texten.",
  "What happened, what you did": "Vad som hände, vad du gjorde",
  "What happens second by second": "Vad som händer sekund för sekund",
  "What is {0}?": "Vad är {0}?",
  "What is it about?": "Vad gäller det?",
  "What is needed?": "Vad behövs?",
  "What is the case about": "Vad ärendet gäller",
  "What is wrong?": "Vad är fel?",
  "What makes the best driver": "Vad som gör den bästa föraren",
  "What Movera keeps from the trip price": "Vad Movera behåller av resans pris",
  "What riders paid on average for completed trips, before tips.": "Vad resenärer i snitt betalade för slutförda resor, före dricks.",
  "What the driver sees before accepting, on the Radar card, the Exclusive card and the reservation popup. Switch each detail on or off.": "Vad föraren ser innan hen accepterar, på radarkortet, det exklusiva kortet och bokningspopupen. Slå på eller av varje detalj.",
  "What the driver sees, {0}": "Vad föraren ser, {0}",
  "What the driver's offer card shows": "Vad förarens erbjudandekort visar",
  "What the rider app asks when the rider cancels.": "Det resenärsappen frågar när resenären avbokar.",
  "What the rider can pay with, and the language each app starts in. The same four methods are offered in every country; untick one to turn it off there. The wallet stays: one balance per currency, used first (Features › Wallet).": "Vad resenären kan betala med och vilket språk varje app startar på. Samma fyra metoder erbjuds i alla länder; avmarkera en för att stänga av den där. Plånboken finns kvar: ett saldo per valuta, används först (Funktioner › Plånbok).",
  "What the rider sees while waiting": "Vad resenären ser medan hen väntar",
  "What to copy": "Vad som ska kopieras",
  "What was done (optional)": "Vad som gjordes (valfritt)",
