  "Winning order: global → market → zone → category → app → platform → app version → cohort.": "Vinnande ordning: global → marknad → zon → kategori → app → plattform → appversion → kohort.",
  "With Movera 3+ months and ride often": "Med Movera i 3+ månader och åker ofta",
  "With promotion": "Med kampanj",
  "With ranges, the whole pickup is paid at the rate of the range its km falls into (exactly 10 km is in 0–10). Ranges go up with no gaps; only the last can be \"and above\", and longer pickups than a closed last range use the last range.": "Med intervall betalas hela körningen till upphämtningen enligt priset för intervallet där dess km hamnar (exakt 10 km ligger i 0–10). Intervallen stiger utan luckor; bara det sista kan vara ”och uppåt”, och längre körningar än ett stängt sista intervall använder det sista intervallet.",
